let compressions=0,shockReady=!1;function startStage4(){compressions=0,shockReady=!1,stageContent.innerHTML='\n\n        <div class="card resuscitation-card">\n\n\n            <h1>\n                🫀 Resuscitation\n            </h1>\n\n\n            <p class="stage-description">\n\n                Patient has no pulse.\n                Start CPR immediately.\n\n            </p>\n\n\n\n            <div class="heart-monitor">\n\n\n                ❤️\n\n\n                <div id="pulse-status">\n\n                    NO PULSE\n\n                </div>\n\n\n            </div>\n\n\n\n            <div id="compression-count">\n\n                Compressions:\n                0 / 30\n\n            </div>\n\n\n\n            <button\n                id="compression-btn">\n\n                ❤️ Perform Compression\n\n            </button>\n\n\n\n\n            <div\n                id="defib-section"\n                class="hidden">\n\n\n                <h2>\n\n                    ⚡ Defibrillator Ready\n\n                </h2>\n\n\n                <p>\n\n                    Shockable rhythm detected.\n\n                </p>\n\n\n                <button\n                    id="charge-btn">\n\n                    ⚡ Charge Defibrillator\n\n                </button>\n\n\n\n            </div>\n\n\n\n\n            <div\n                id="shock-section"\n                class="hidden">\n\n\n                <h2>\n\n                    ⚡ Ready To Shock\n\n                </h2>\n\n\n                <button\n                    id="shock-btn">\n\n                    ⚡ DELIVER SHOCK\n\n                </button>\n\n\n            </div>\n\n\n\n        </div>\n\n    ',document.getElementById("compression-btn").onclick=()=>{compressions++,playSound("beep"),document.getElementById("compression-count").textContent=`\n        Compressions:\n        ${compressions} / 30\n        `,compressions>=30&&(document.getElementById("defib-section").classList.remove("hidden"),document.getElementById("compression-btn").disabled=!0,playSound("success"))},document.getElementById("charge-btn").onclick=n=>{const e=n.currentTarget;e.disabled=!0,e.textContent="⚡ Charging...",playSound("shock"),document.getElementById("defib-section").innerHTML='\n\n            <h2>\n                ⚡ Charging...\n            </h2>\n\n\n            <div class="charge-bar">\n\n                <div></div>\n\n            </div>\n\n            <p>\n                Do not touch patient\n            </p>\n\n        ',setTimeout((()=>{shockReady=!0,document.getElementById("shock-section").classList.remove("hidden")}),2500)},document.getElementById("shock-btn").onclick=()=>{if(!shockReady)return;shockReady=!1,playSound("shock");const n=document.querySelector(".heart-monitor");n&&n.classList.add("shock-animation"),updatePatientState("stabilized"),transition("❤️ Rhythm Restored","Patient stabilized. Preparing certificate...",(()=>{completedStage=4,stageCompleted()}))}}